-- Обязательные атрибуты field/well и поддерживаемая ISO-дата valid_from; D проверяется так же, как U.
WITH p AS (SELECT event_type,try(json_parse(payload)) AS j FROM {{target:oil_stg__v_event_parsed}}) SELECT count(*) AS n FROM p WHERE (event_type='field' AND (nullif(json_extract_scalar(j,'$.field_name'),'') IS NULL OR nullif(json_extract_scalar(j,'$.region'),'') IS NULL)) OR (event_type='well' AND (json_extract_scalar(j,'$.field_id') IS NULL OR NOT regexp_like(json_extract_scalar(j,'$.field_id'),'^[A-Za-z0-9_-]+$') OR nullif(json_extract_scalar(j,'$.well_name'),'') IS NULL OR json_extract_scalar(j,'$.valid_from') IS NULL OR NOT regexp_like(json_extract_scalar(j,'$.valid_from'),'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') OR try_cast(json_extract_scalar(j,'$.valid_from') AS date) IS NULL OR json_extract_scalar(j,'$.status') IS NULL OR json_extract_scalar(j,'$.status') NOT IN ('ACTIVE','INACTIVE')));
